import requests
def task_func(url="http://example.com", from_encoding="cp1251", use_lxml=False):
    if not url:
        return None
    try:
        response = requests.get(url, timeout=10, verify=False)
        if response.status_code != 200:
            return None
        content = response.content.decode(from_encoding)
        if use_lxml:
            soup = BeautifulSoup(content, 'lxml')
        else:
            soup = BeautifulSoup(content, 'html.parser')
        return soup
    except Exception:
        return None

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    raw_data = response.content
    if not raw_data:
        return {}
    if from_encoding is None:
        detected = chardet.detect(raw_data)
        if detected['confidence'] < 0.5:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    decoded = raw_data.decode(from_encoding)
    re_encoded = decoded.encode(to_encoding)
    return json.loads(re_encoded)

import requests
import logging

def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, timeout=10, verify=False)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 429:
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

    repo_info = response.json()
    open_issues = repo_info.get("open_issues_count", 0)
    if open_issues > 100:
        logging.warning(f"High number of open issues: {open_issues}")

    return repo_info

