def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"\']+|www\.[^\s<>"\']+'
    urls = re.findall(url_pattern, myString)
    results = {}
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc if parsed.netloc else parsed.path.split('/')[0]
            if not domain:
                continue
            response = requests.get(f'http://api.ipapi.com/{domain}?access_key={API_KEY}')
            results[domain] = response.json() if response.status_code == 200 else None
        except:
            results[domain] = None
    return results

