import json
import requests
import os
from datetime import datetime

def task_func(json_data, unknown_key, save_dir=None):
    data = json.loads(json_data)
    if unknown_key not in data:
        raise ValueError(f"Key '{unknown_key}' not found in JSON data.")
    url = data[unknown_key]
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL retrieved from JSON data.")

    timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
    filename = f"{unknown_key}_{timestamp}.txt"
    if save_dir:
        os.makedirs(save_dir, exist_ok=True)
        file_path = os.path.join(save_dir, filename)
    else:
        file_path = filename

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(response.text)
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from {url}: {e}")

    return os.path.abspath(file_path)

import ipaddress
import requests

def task_func(ip_range, timeout):
    try:
        network = ipaddress.IPv4Network(ip_range, strict=False)
    except Exception:
        raise ValueError("Invalid IP range provided.")

    active_ips = []
    for host in network.hosts():
        url = f"http://{host}:80"
        try:
            resp = requests.get(url, timeout=timeout)
            if resp.status_code == 200:
                active_ips.append(str(host))
        except Exception:
            continue
    return active_ips

import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url or not isinstance(url, str):
        raise ValueError("Invalid URL.")
    if not destination_directory or not os.path.isdir(destination_directory):
        raise ValueError("Invalid destination directory.")
    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download the ZIP file: {e}")

    zip_path = os.path.join(destination_directory, 'downloaded.zip')
    with open(zip_path, 'wb') as f:
        f.write(response.content)

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            zf.extractall(destination_directory)
            extracted_files = zf.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid or corrupted ZIP file: {e}")

    return extracted_files

import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(parameters, dict):
        raise Exception("Invalid URL or parameters provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to access the API: {e}")
    try:
        data = response.json()
        if not data:
            raise Exception("No data returned from the API.")
    except json.JSONDecodeError:
        raise Exception("Invalid JSON data received.")
    try:
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty.")
    except Exception as e:
        raise Exception(f"Error creating DataFrame: {e}")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical data available for correlation.")
    corr_matrix = numeric_df.corr()
    plt.figure(figsize=(10, 8))
    ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', center=0)
    ax.set_title('Correlation Heatmap')
    plt.tight_layout()
    return df, ax

